import React from 'react';

import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import PohAlert from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { getHikingDataAsync } from '../../@services/hiking.service';
import { getHikingFinancesReceipts } from '../../@services/hikingFinances.service';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingReceipt } from '../../@types/hikingFinances.types';
import ViewReceiptModal from '../HikingFinancesModals/ViewReceiptModal';

interface IHikingFinancesOneReceiptPageProps {
  id_hiking: number;
  id_receipt: number;
}

const HikingFinancesOneReceiptPage: React.FC<IHikingFinancesOneReceiptPageProps> = ({
  id_hiking,
  id_receipt,
}) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);

  const [receipt, setReceipt] = React.useState<IHikingReceipt>();

  const [err, setErr] = React.useState<string | undefined>(undefined);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const hData = await getHikingDataAsync(id_hiking);
        setHikingData(hData);

        const receiptData = await getHikingFinancesReceipts({ id: id_receipt });
        setReceipt(receiptData[0]);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id_hiking, id_receipt]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err || !hikingData || !receipt) {
    return <PohAlert>{err}</PohAlert>;
  }

  return (
    <Page title={`${receipt.name} | ${hikingData.name}`}>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/finances`, text: 'Финансы' },
          {
            href: `/hiking/${id_hiking}/finances/${id_receipt}`,
            text: receipt.name,
            active: true,
          },
        ]}
      />
      <PohContainer>
        <PageHeader title={`Чек похода«${hikingData.name}»`} subtitle={receipt.name}></PageHeader>
        <PohRow>
          <PohCol sm={12}>
            <ViewReceiptModal receipt={receipt} hikingData={hikingData} />
          </PohCol>
        </PohRow>
      </PohContainer>
    </Page>
  );
};

export default HikingFinancesOneReceiptPage;
